"""Source-specific adult renal additions and readable text controls.

Build after releases 0.6, 0.7 and 0.8. Source review is not clinical approval.
"""
from pathlib import Path
import json
R=Path(__file__).parent;D=R/'dist';DATE='2026-10-29'
data=json.loads((D/'database.json').read_text());assert data['version']=='0.8.0'
drugs={d['id']:d for d in data['drugs']};old=json.loads(json.dumps(drugs))
sources={s['id']:s for s in data['sources']}
NM='https://www.unmc.edu/intmed/_documents/id/asp/dose-nm-anti-infective-renal-dosing-guidelines.pdf'
def source(ident,url,section,kind='Product prescribing information',pages=None,title=None):
 sid='v09-'+ident
 sources[sid]=dict(id=sid,title=title or drugs[ident]['name']+' · selected renal information',url=url,section=section,type=kind,accessed=DATE)
 if pages:
  f=data['sourceAudit'][4];sources[sid]['suppliedDocument']=dict(fileName=f['fileName'],sha256=f['sha256'],pdfPage=pages[0],additionalPdfPages=pages[1:],editionOrDate=f['editionOrDate'])
 return sid
def nm(ident,*pages):return source(ident,NM+'#page='+str(pages[0]),'Adult rows only; PDF pages '+', '.join(map(str,pages))+'. P&T approval April 2026. Not paediatric or intraperitoneal regimens.','Supplied institutional protocol',pages,'Nebraska adult protocol · '+drugs[ident]['name'])
def label(ident,setid,section='Renal impairment, dosing and formulation-specific warnings'):
 return source(ident,'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid='+setid,section)
def tab(title,rows):return dict(indication=title,rows=[dict(context=c,dose=v) for c,v in rows])
def mod(ref,title=None,rows=None,notes='',status=None):return dict(status=status or ('summarized' if rows else 'specialist'),tables=[tab(title,rows)] if rows else [],notes=notes,sourceIds=[ref])
def add(ident,ref,summary,rows=None,title='Selected adult renal guidance',notes='',flag='adjust',form=None,metric='CrCl · mL/min; confirm source method',status=None):
 d=drugs[ident];assert d['entryType']=='catalog',ident
 d.update(entryType='renal',summary=summary,flag=flag,sourceIds=[ref],kidneyMetric=metric,updatedInVersion='0.9.0',jurisdiction='Selected source-specific adult guidance; not an independently approved or complete prescribing monograph.',completeness='Only the displayed route, indication and source statement are reviewed. Other indications, formulations and RRT prescriptions remain separate; no missing dose is inferred.',considerations=notes)
 if form:
  d['formulation']=form
  if form.startswith('Oral'):d['routes']=['Oral']
  elif form.startswith(('IV','Injection','Systemic IV','SC')):d['routes']=['Parenteral']
  elif form.startswith(('PO / IV','PO or IV')):d['routes']=['Oral','Parenteral']
 d['review']['sourceCheckedAt']=DATE;d['modalities']['ckd']=mod(ref,title,rows,notes,status)
 return d
def noadj(ident,page,form,notes=''):
 r=nm(ident,page);return add(ident,r,'The selected adult protocol gives no renal reduction; choose the full indication-specific regimen separately.',[('Renal impairment','No renal dose reduction specified in this protocol')],notes=notes,flag='no_adjust',form=form)
def rrt(d,key,ref,title,rows=None,notes='',status=None):d['modalities'][key]=mod(ref,title,rows,notes,status)

