def fact(value,ref,context,basis=None):
 f=dict(status='sourced' if value is not None else 'not_reported',value=value,context=context,sourceIds=[ref])
 if basis:f['basis']=basis
 return f
for ident,page,half,renal,vd,pb,hd,pd,note in pk_rows:
 d=drugs[ident];assert d['pharmacokinetics']['status']=='not_curated',ident
 ref='rdh5-v09-'+ident;file=data['sourceAudit'][0]
 sources[ref]=dict(id=ref,title=f'Renal Drug Handbook 5th · {d["name"]} · PDF p{page} (printed {page-19})',url=BOOK,section=f'Supplied fifth edition, published 2018 (copyright 2019), PDF p{page}; PK table and method-specific removal. Link is a publisher listing, not this supplied PDF.',type='Supplied historical PK reference',accessed=DATE,suppliedDocument=dict(fileName=file['fileName'],sha256=file['sha256'],pdfPage=page,editionOrDate=file['editionOrDate']))
 def removal(value,context):
  status='unknown' if value is None else 'limited' if 'unknown' in value or 'unlikely' in value.lower() else 'not_removed' if value.startswith('Not removed') else 'removed'
  return dict(status=status,value=value,context=context,sourceIds=[ref])
 missing=lambda:dict(status='not_curated',value=None,context='No prescription-specific removal value curated.',sourceIds=[])
 d['pharmacokinetics']=dict(status='source_summary',sourceCheckedAt=DATE,historical=True,evidenceDate='2018 (copyright 2019)',halfLife=fact(half,ref,'Historical normal/reference column. '+note),renalHalfLife=fact(renal,ref,'Historical ESRF column; not an on-dialysis half-life.','handbook_normal_esrf_columns'),volumeOfDistribution=fact(vd,ref,note),proteinBinding=fact(pb,ref,'Historical plasma binding reference; clinical state and measurement can affect the unbound fraction.'),dialysability=dict(ihd=removal(hd,'Historical method categories; no measured modern clearance extent implied.'),pd=removal(pd,'Historical APD/CAPD category; not a PD dose recommendation.'),crrt=missing(),sled=missing()),notes='Historical fifth-edition PK, published 2018 (copyright 2019); not newly measured data or independent clinical approval. '+note)
 d['updatedInVersion']='0.9.0'

